See:https://godbolt.org/z/9jvYTfYE4```
struct QQQ {
    consteval QQQ(std::string_view d): data(d) {}
    std::string_view data;
};

void sink(const QQQ&);

void f() {
    QQQ q("dogsdogsdogs");
    sink(q);
}
```

